-- ═══════════════════════════════════════════════════════════════
-- FILE: sql/015_atomic_supplier_stock_dispatch.sql
-- ═══════════════════════════════════════════════════════════════

-- AuroWater: atomic supplier stock reservation + deterministic geo dispatch
-- Safe/idempotent. Apply after existing migrations. Re-run is safe.

BEGIN;

ALTER TABLE public.addresses
  ADD COLUMN IF NOT EXISTS lat DOUBLE PRECISION,
  ADD COLUMN IF NOT EXISTS lng DOUBLE PRECISION;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='addresses_lat_valid' AND conrelid='public.addresses'::regclass) THEN
    ALTER TABLE public.addresses ADD CONSTRAINT addresses_lat_valid CHECK (lat IS NULL OR lat BETWEEN -90 AND 90);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='addresses_lng_valid' AND conrelid='public.addresses'::regclass) THEN
    ALTER TABLE public.addresses ADD CONSTRAINT addresses_lng_valid CHECK (lng IS NULL OR lng BETWEEN -180 AND 180);
  END IF;
END $$;

ALTER TABLE public.supplier_settings
  ADD COLUMN IF NOT EXISTS base_lat DOUBLE PRECISION,
  ADD COLUMN IF NOT EXISTS base_lng DOUBLE PRECISION;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='supplier_settings_base_lat_valid' AND conrelid='public.supplier_settings'::regclass) THEN
    ALTER TABLE public.supplier_settings ADD CONSTRAINT supplier_settings_base_lat_valid CHECK (base_lat IS NULL OR base_lat BETWEEN -90 AND 90);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='supplier_settings_base_lng_valid' AND conrelid='public.supplier_settings'::regclass) THEN
    ALTER TABLE public.supplier_settings ADD CONSTRAINT supplier_settings_base_lng_valid CHECK (base_lng IS NULL OR base_lng BETWEEN -180 AND 180);
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS public.order_dispatch (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  supplier_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'ASSIGNED'
    CHECK (status IN ('ASSIGNED','ACCEPTED','REJECTED','EXPIRED','CANCELLED')),
  distance_km NUMERIC(10,2),
  responded_at TIMESTAMPTZ,
  reason TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_order_dispatch_order_created ON public.order_dispatch(order_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_order_dispatch_supplier_status ON public.order_dispatch(supplier_id, status);
ALTER TABLE public.order_dispatch ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS order_dispatch_supplier_read ON public.order_dispatch;
CREATE POLICY order_dispatch_supplier_read ON public.order_dispatch FOR SELECT TO authenticated
  USING (supplier_id = auth.uid());

DROP POLICY IF EXISTS order_dispatch_customer_read ON public.order_dispatch;
CREATE POLICY order_dispatch_customer_read ON public.order_dispatch FOR SELECT TO authenticated
  USING (EXISTS (SELECT 1 FROM public.orders o WHERE o.id = order_dispatch.order_id AND o.customer_id = auth.uid()));

DROP POLICY IF EXISTS order_dispatch_admin_all ON public.order_dispatch;
CREATE POLICY order_dispatch_admin_all ON public.order_dispatch FOR ALL TO authenticated
  USING (COALESCE(public.current_profile_role(), '') = 'admin')
  WITH CHECK (COALESCE(public.current_profile_role(), '') = 'admin');

-- Browser clients read inventory/dispatch state but cannot mutate reservation fields directly.
-- All writes go through the locked SECURITY DEFINER RPCs above.
REVOKE INSERT, UPDATE, DELETE ON public.supplier_stock FROM authenticated;
GRANT SELECT ON public.supplier_stock TO authenticated;
REVOKE INSERT, UPDATE, DELETE ON public.order_dispatch FROM authenticated;
GRANT SELECT ON public.order_dispatch TO authenticated;

ALTER TABLE public.supplier_stock
  ADD COLUMN IF NOT EXISTS reserved_cans INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS reservation_buffer_cans INTEGER NOT NULL DEFAULT 0;
ALTER TABLE public.supplier_stock DROP CONSTRAINT IF EXISTS supplier_stock_available_valid;
ALTER TABLE public.supplier_stock DROP CONSTRAINT IF EXISTS supplier_stock_reserved_valid;
ALTER TABLE public.supplier_stock DROP CONSTRAINT IF EXISTS supplier_stock_buffer_valid;
ALTER TABLE public.supplier_stock
  ADD CONSTRAINT supplier_stock_available_valid CHECK (cans_available >= 0),
  ADD CONSTRAINT supplier_stock_reserved_valid CHECK (reserved_cans >= 0 AND reserved_cans <= cans_available),
  ADD CONSTRAINT supplier_stock_buffer_valid CHECK (reservation_buffer_cans >= 0);

ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS stock_reserved_quantity INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS stock_reservation_status TEXT NOT NULL DEFAULT 'none',
  ADD COLUMN IF NOT EXISTS stock_reserved_supplier_id UUID REFERENCES public.profiles(id),
  ADD COLUMN IF NOT EXISTS stock_reserved_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS stock_released_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS stock_consumed_at TIMESTAMPTZ;
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_stock_reservation_status_check;
ALTER TABLE public.orders DROP CONSTRAINT IF EXISTS orders_stock_reserved_quantity_check;
ALTER TABLE public.orders
  ADD CONSTRAINT orders_stock_reservation_status_check CHECK (stock_reservation_status IN ('none','reserved','released','consumed')),
  ADD CONSTRAINT orders_stock_reserved_quantity_check CHECK (stock_reserved_quantity >= 0);
CREATE INDEX IF NOT EXISTS idx_orders_stock_reservation ON public.orders(stock_reservation_status, stock_reserved_supplier_id);

-- Remove the old non-atomic completion trigger from PATCH_001.
DROP TRIGGER IF EXISTS trg_deduct_stock ON public.orders;
DROP FUNCTION IF EXISTS public.deduct_supplier_stock();

CREATE OR REPLACE FUNCTION public.adjust_supplier_stock(
  p_supplier_id UUID,
  p_delta INTEGER,
  p_low_stock_alert INTEGER DEFAULT NULL,
  p_reservation_buffer_cans INTEGER DEFAULT NULL
) RETURNS public.supplier_stock
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.supplier_stock; next_available INTEGER;
BEGIN
  IF auth.role() <> 'service_role' AND auth.uid() IS DISTINCT FROM p_supplier_id AND public.current_profile_role() <> 'admin' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF p_delta IS NULL OR p_delta < -100000 OR p_delta > 100000 THEN RAISE EXCEPTION 'INVALID_STOCK_ADJUSTMENT'; END IF;
  INSERT INTO public.supplier_stock(supplier_id) VALUES(p_supplier_id) ON CONFLICT(supplier_id) DO NOTHING;
  SELECT * INTO r FROM public.supplier_stock WHERE supplier_id=p_supplier_id FOR UPDATE;
  next_available := r.cans_available + p_delta;
  IF next_available < r.reserved_cans THEN RAISE EXCEPTION 'STOCK_BELOW_RESERVED'; END IF;
  UPDATE public.supplier_stock
    SET cans_available=next_available,
        low_stock_alert=COALESCE(p_low_stock_alert,low_stock_alert),
        reservation_buffer_cans=COALESCE(p_reservation_buffer_cans,reservation_buffer_cans),
        updated_at=now()
    WHERE supplier_id=p_supplier_id RETURNING * INTO r;
  RETURN r;
END; $$;

CREATE OR REPLACE FUNCTION public.set_supplier_stock(
  p_supplier_id UUID,
  p_cans_available INTEGER,
  p_low_stock_alert INTEGER DEFAULT NULL,
  p_reservation_buffer_cans INTEGER DEFAULT NULL
) RETURNS public.supplier_stock
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE r public.supplier_stock;
BEGIN
  IF auth.role() <> 'service_role' AND auth.uid() IS DISTINCT FROM p_supplier_id AND public.current_profile_role() <> 'admin' THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF p_cans_available IS NULL OR p_cans_available < 0 OR p_cans_available > 100000 THEN RAISE EXCEPTION 'INVALID_STOCK'; END IF;
  INSERT INTO public.supplier_stock(supplier_id) VALUES(p_supplier_id) ON CONFLICT(supplier_id) DO NOTHING;
  SELECT * INTO r FROM public.supplier_stock WHERE supplier_id=p_supplier_id FOR UPDATE;
  IF p_cans_available < r.reserved_cans THEN RAISE EXCEPTION 'STOCK_BELOW_RESERVED'; END IF;
  UPDATE public.supplier_stock
    SET cans_available=p_cans_available,
        low_stock_alert=COALESCE(p_low_stock_alert,low_stock_alert),
        reservation_buffer_cans=COALESCE(p_reservation_buffer_cans,reservation_buffer_cans),
        updated_at=now()
    WHERE supplier_id=p_supplier_id RETURNING * INTO r;
  RETURN r;
END; $$;

CREATE OR REPLACE FUNCTION public.try_assign_supplier_with_stock(
  p_order_id UUID,
  p_supplier_id UUID,
  p_distance_km NUMERIC DEFAULT NULL
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE o public.orders; s public.supplier_stock; qty INTEGER; now_ts TIMESTAMPTZ:=now();
BEGIN
  IF auth.role() <> 'service_role' AND public.current_profile_role() <> 'admin' AND auth.uid() IS DISTINCT FROM p_supplier_id THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  SELECT * INTO o FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND OR o.status <> 'PENDING' OR o.supplier_id IS NOT NULL THEN RETURN FALSE; END IF;
  qty:=GREATEST(0,COALESCE(o.can_count,0));
  IF qty <= 0 THEN
    INSERT INTO public.order_dispatch(order_id,supplier_id,status,distance_km,created_at) VALUES(p_order_id,p_supplier_id,'ASSIGNED',p_distance_km,now_ts);
    UPDATE public.orders SET supplier_id=p_supplier_id,status='ASSIGNED',assigned_at=now_ts,last_dispatch_at=now_ts,dispatch_attempts=COALESCE(dispatch_attempts,0)+1 WHERE id=p_order_id;
    RETURN TRUE;
  END IF;
  SELECT * INTO s FROM public.supplier_stock WHERE supplier_id=p_supplier_id FOR UPDATE;
  IF NOT FOUND OR s.cans_available-s.reserved_cans-s.reservation_buffer_cans < qty THEN RETURN FALSE; END IF;
  INSERT INTO public.order_dispatch(order_id,supplier_id,status,distance_km,created_at) VALUES(p_order_id,p_supplier_id,'ASSIGNED',p_distance_km,now_ts);
  UPDATE public.supplier_stock SET reserved_cans=reserved_cans+qty,updated_at=now_ts WHERE supplier_id=p_supplier_id;
  UPDATE public.orders SET supplier_id=p_supplier_id,status='ASSIGNED',assigned_at=now_ts,last_dispatch_at=now_ts,
    dispatch_attempts=COALESCE(dispatch_attempts,0)+1,stock_reserved_quantity=qty,stock_reservation_status='reserved',
    stock_reserved_supplier_id=p_supplier_id,stock_reserved_at=now_ts,stock_released_at=NULL,stock_consumed_at=NULL
    WHERE id=p_order_id;
  RETURN TRUE;
EXCEPTION WHEN unique_violation THEN RETURN FALSE;
END; $$;

CREATE OR REPLACE FUNCTION public.sync_order_stock_reservation()
RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE supplier UUID; qty INTEGER;
BEGIN
  IF OLD.stock_reservation_status <> 'reserved' OR OLD.stock_reserved_quantity <= 0 OR OLD.stock_reserved_supplier_id IS NULL THEN RETURN NEW; END IF;
  supplier:=OLD.stock_reserved_supplier_id; qty:=OLD.stock_reserved_quantity;
  IF NEW.status='COMPLETED' AND OLD.status<>'COMPLETED' THEN
    UPDATE public.supplier_stock SET cans_available=GREATEST(0,cans_available-qty),reserved_cans=GREATEST(0,reserved_cans-qty),updated_at=now() WHERE supplier_id=supplier;
    NEW.stock_reservation_status:='consumed'; NEW.stock_consumed_at:=now(); NEW.stock_reserved_quantity:=0;
    RETURN NEW;
  END IF;
  IF NEW.status='CANCELLED' OR (NEW.status='PENDING' AND NEW.supplier_id IS NULL AND OLD.supplier_id IS NOT NULL) THEN
    UPDATE public.supplier_stock SET reserved_cans=GREATEST(0,reserved_cans-qty),updated_at=now() WHERE supplier_id=supplier;
    NEW.stock_reservation_status:='released'; NEW.stock_released_at:=now(); NEW.stock_reserved_quantity:=0; NEW.stock_reserved_supplier_id:=NULL;
    RETURN NEW;
  END IF;
  RETURN NEW;
END; $$;

DROP TRIGGER IF EXISTS trg_sync_order_stock_reservation ON public.orders;
CREATE TRIGGER trg_sync_order_stock_reservation BEFORE UPDATE OF status,supplier_id ON public.orders
FOR EACH ROW EXECUTE FUNCTION public.sync_order_stock_reservation();

GRANT EXECUTE ON FUNCTION public.adjust_supplier_stock(UUID,INTEGER,INTEGER,INTEGER) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.set_supplier_stock(UUID,INTEGER,INTEGER,INTEGER) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.try_assign_supplier_with_stock(UUID,UUID,NUMERIC) TO authenticated,service_role;

COMMIT;
SELECT pg_notify('pgrst','reload schema');


-- ═══════════════════════════════════════════════════════════════
-- FILE: sql/016_atomic_technician_dispatch.sql
-- ═══════════════════════════════════════════════════════════════

-- AuroWater technician atomic dispatch, trust, OTP proof and complaint hardening.
-- Safe/idempotent. APPLY ONLY AFTER 015_atomic_supplier_stock_dispatch.sql.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

INSERT INTO public.settings (key, value)
VALUES ('technician_max_active_jobs','3'), ('technician_service_radius_km','15')
ON CONFLICT (key) DO NOTHING;

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS current_lat DOUBLE PRECISION,
  ADD COLUMN IF NOT EXISTS current_lng DOUBLE PRECISION,
  ADD COLUMN IF NOT EXISTS verification_status TEXT,
  ADD COLUMN IF NOT EXISTS availability_status TEXT DEFAULT 'available';

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='profiles_current_lat_valid' AND conrelid='public.profiles'::regclass) THEN
    ALTER TABLE public.profiles ADD CONSTRAINT profiles_current_lat_valid CHECK (current_lat IS NULL OR current_lat BETWEEN -90 AND 90);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='profiles_current_lng_valid' AND conrelid='public.profiles'::regclass) THEN
    ALTER TABLE public.profiles ADD CONSTRAINT profiles_current_lng_valid CHECK (current_lng IS NULL OR current_lng BETWEEN -180 AND 180);
  END IF;
END $$;

ALTER TABLE public.orders
  ADD COLUMN IF NOT EXISTS technician_dispatch_attempts INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS last_technician_dispatch_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS service_otp_hash TEXT,
  ADD COLUMN IF NOT EXISTS service_otp_created_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS service_otp_verified BOOLEAN NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS service_started_at TIMESTAMPTZ;

CREATE TABLE IF NOT EXISTS public.technician_job_dispatch (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  order_id UUID NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,
  technician_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'OFFERED'
    CHECK (status IN ('OFFERED','ACCEPTED','REJECTED','EXPIRED','CANCELLED','COMPLETED')),
  distance_km NUMERIC(10,2),
  trust_score NUMERIC(6,2),
  reason TEXT,
  responded_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(order_id, technician_id)
);

CREATE INDEX IF NOT EXISTS technician_job_dispatch_order_idx
  ON public.technician_job_dispatch(order_id, created_at DESC);
CREATE INDEX IF NOT EXISTS technician_job_dispatch_technician_idx
  ON public.technician_job_dispatch(technician_id, status);
CREATE INDEX IF NOT EXISTS technician_job_dispatch_status_idx
  ON public.technician_job_dispatch(status);

ALTER TABLE public.technician_job_dispatch ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS technician_dispatch_technician_read ON public.technician_job_dispatch;
CREATE POLICY technician_dispatch_technician_read
  ON public.technician_job_dispatch FOR SELECT TO authenticated
  USING (technician_id = auth.uid());

DROP POLICY IF EXISTS technician_dispatch_customer_read ON public.technician_job_dispatch;
CREATE POLICY technician_dispatch_customer_read
  ON public.technician_job_dispatch FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.orders o
    WHERE o.id = technician_job_dispatch.order_id
      AND o.customer_id = auth.uid()
  ));

DROP POLICY IF EXISTS technician_dispatch_admin_all ON public.technician_job_dispatch;
CREATE POLICY technician_dispatch_admin_all
  ON public.technician_job_dispatch FOR ALL TO authenticated
  USING (COALESCE(public.current_profile_role(), '') = 'admin')
  WITH CHECK (COALESCE(public.current_profile_role(), '') = 'admin');

REVOKE INSERT, UPDATE, DELETE ON public.technician_job_dispatch FROM authenticated;
GRANT SELECT ON public.technician_job_dispatch TO authenticated;

CREATE OR REPLACE FUNCTION public.try_assign_technician(
  p_order_id UUID,
  p_technician_id UUID,
  p_distance_km NUMERIC DEFAULT NULL,
  p_trust_score NUMERIC DEFAULT NULL
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $$
DECLARE
  o public.orders;
  p public.profiles;
  max_active INTEGER := 3;
  radius_km NUMERIC := 15;
  active_count INTEGER;
  now_ts TIMESTAMPTZ := now();
BEGIN
  IF auth.role() <> 'service_role'
     AND public.current_profile_role() <> 'admin'
     AND auth.uid() IS DISTINCT FROM p_technician_id
  THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  SELECT * INTO o FROM public.orders WHERE id=p_order_id FOR UPDATE;
  IF NOT FOUND OR o.status <> 'PENDING' OR o.technician_id IS NOT NULL THEN RETURN FALSE; END IF;

  SELECT * INTO p FROM public.profiles
  WHERE id=p_technician_id
    AND role='technician'
    AND is_active=true
    AND lower(COALESCE(status,''))='active'
    AND (verification_status IS NULL OR lower(verification_status)='approved')
    AND lower(COALESCE(availability_status,'available')) IN ('available','online')
  FOR UPDATE;

  IF NOT FOUND THEN RETURN FALSE; END IF;

  SELECT COALESCE(NULLIF(value,'')::INTEGER,3) INTO max_active
  FROM public.settings WHERE key='technician_max_active_jobs';
  SELECT COALESCE(NULLIF(value,'')::NUMERIC,15) INTO radius_km
  FROM public.settings WHERE key='technician_service_radius_km';

  SELECT COUNT(*) INTO active_count
  FROM public.orders
  WHERE technician_id=p_technician_id
    AND status IN ('ASSIGNED','IN_PROGRESS');

  IF active_count >= max_active THEN RETURN FALSE; END IF;

  IF p_distance_km IS NOT NULL AND p_distance_km > radius_km THEN RETURN FALSE; END IF;

  INSERT INTO public.technician_job_dispatch(
    order_id, technician_id, status, distance_km, trust_score, created_at
  ) VALUES (
    p_order_id, p_technician_id, 'OFFERED', p_distance_km, p_trust_score, now_ts
  )
  ON CONFLICT (order_id, technician_id) DO NOTHING;

  IF NOT FOUND THEN RETURN FALSE; END IF;

  UPDATE public.orders
  SET technician_id=p_technician_id,
      status='ASSIGNED',
      assigned_at=COALESCE(assigned_at,now_ts),
      last_technician_dispatch_at=now_ts,
      technician_dispatch_attempts=COALESCE(technician_dispatch_attempts,0)+1
  WHERE id=p_order_id
    AND status='PENDING'
    AND technician_id IS NULL;

  IF NOT FOUND THEN
    UPDATE public.technician_job_dispatch
      SET status='CANCELLED', responded_at=now_ts, reason='order_no_longer_pending'
    WHERE order_id=p_order_id AND technician_id=p_technician_id AND status='OFFERED';
    RETURN FALSE;
  END IF;

  RETURN TRUE;
END;
$$;

CREATE OR REPLACE FUNCTION public.accept_technician_job(
  p_order_id UUID,
  p_technician_id UUID
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $$
BEGIN
  IF auth.role() <> 'service_role' AND auth.uid() IS DISTINCT FROM p_technician_id THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;

  UPDATE public.technician_job_dispatch
  SET status='ACCEPTED', responded_at=now()
  WHERE order_id=p_order_id
    AND technician_id=p_technician_id
    AND status='OFFERED';

  RETURN FOUND;
END;
$$;

CREATE OR REPLACE FUNCTION public.start_technician_job(
  p_order_id UUID,
  p_technician_id UUID
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $$
BEGIN
  IF auth.role() <> 'service_role' AND auth.uid() IS DISTINCT FROM p_technician_id THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;

  UPDATE public.orders
  SET status='IN_PROGRESS',
      service_started_at=now()
  WHERE id=p_order_id
    AND technician_id=p_technician_id
    AND status='ASSIGNED'
    AND EXISTS (
      SELECT 1 FROM public.technician_job_dispatch d
      WHERE d.order_id=p_order_id
        AND d.technician_id=p_technician_id
        AND d.status='ACCEPTED'
    );

  RETURN FOUND;
END;
$$;

CREATE OR REPLACE FUNCTION public.release_technician_assignment(
  p_order_id UUID,
  p_technician_id UUID,
  p_reason TEXT DEFAULT 'REJECTED'
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $
DECLARE
  o public.orders;
BEGIN
  IF auth.role() <> 'service_role' AND auth.uid() IS DISTINCT FROM p_technician_id THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;

  SELECT * INTO o FROM public.orders
  WHERE id=p_order_id
    AND technician_id=p_technician_id
    AND status='ASSIGNED'
  FOR UPDATE;

  IF NOT FOUND THEN RETURN FALSE; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.technician_job_dispatch
    WHERE order_id=p_order_id
      AND technician_id=p_technician_id
      AND status='OFFERED'
  ) THEN
    RETURN FALSE;
  END IF;

  UPDATE public.technician_job_dispatch
  SET status=CASE WHEN upper(p_reason)='EXPIRED' THEN 'EXPIRED' ELSE 'REJECTED' END,
      responded_at=now(),
      reason=p_reason
  WHERE order_id=p_order_id
    AND technician_id=p_technician_id
    AND status='OFFERED';

  UPDATE public.orders
  SET technician_id=NULL,
      status='PENDING',
      assigned_at=NULL,
      last_technician_dispatch_at=now()
  WHERE id=p_order_id;

  RETURN TRUE;
END;
$;

CREATE OR REPLACE FUNCTION public.create_service_otp(
  p_order_id UUID,
  p_technician_id UUID
) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $
DECLARE
  o public.orders;
  code TEXT;
BEGIN
  IF auth.role() <> 'service_role' AND auth.uid() IS DISTINCT FROM p_technician_id THEN
    RAISE EXCEPTION 'FORBIDDEN';
  END IF;

  SELECT * INTO o FROM public.orders
  WHERE id=p_order_id AND technician_id=p_technician_id
  FOR UPDATE;

  IF NOT FOUND OR o.status <> 'IN_PROGRESS' THEN
    RAISE EXCEPTION 'JOB_NOT_IN_PROGRESS';
  END IF;

  code := lpad((floor(random()*1000000))::INTEGER::TEXT,6,'0');

  UPDATE public.orders
  SET service_otp_hash=encode(digest(code,'sha256'),'hex'),
      service_otp_created_at=now(),
      service_otp_verified=false
  WHERE id=p_order_id;

  RETURN code;
END;
$;

CREATE OR REPLACE FUNCTION public.verify_service_otp(
  p_order_id UUID,
  p_otp TEXT,
  p_technician_id UUID
) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $$
DECLARE o public.orders;
BEGIN
  IF auth.role() <> 'service_role'
     AND auth.uid() IS DISTINCT FROM p_technician_id
  THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  IF p_otp !~ '^[0-9]{6}$' THEN RETURN FALSE; END IF;

  SELECT * INTO o FROM public.orders
  WHERE id=p_order_id AND technician_id=p_technician_id
  FOR UPDATE;

  IF NOT FOUND OR o.status <> 'IN_PROGRESS' OR o.service_otp_hash IS NULL THEN RETURN FALSE; END IF;

  IF o.service_otp_hash <> encode(digest(p_otp,'sha256'),'hex') THEN RETURN FALSE; END IF;

  UPDATE public.orders
  SET service_otp_verified=true
  WHERE id=p_order_id;

  UPDATE public.technician_job_dispatch
  SET reason=COALESCE(reason,'') || CASE WHEN COALESCE(reason,'')='' THEN '' ELSE ' | ' END || 'otp_verified'
  WHERE order_id=p_order_id AND technician_id=p_technician_id AND status='ACCEPTED';

  RETURN TRUE;
END;
$$;

CREATE OR REPLACE FUNCTION public.complete_technician_job_atomic(
  p_order_id UUID,
  p_technician_id UUID,
  p_payment_confirmed BOOLEAN DEFAULT FALSE,
  p_payment_reference TEXT DEFAULT NULL
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path=''
AS $$
DECLARE
  o public.orders;
  now_ts TIMESTAMPTZ := now();
BEGIN
  IF auth.role() <> 'service_role'
     AND auth.uid() IS DISTINCT FROM p_technician_id
  THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;

  SELECT * INTO o FROM public.orders
  WHERE id=p_order_id AND technician_id=p_technician_id
  FOR UPDATE;

  IF NOT FOUND THEN RAISE EXCEPTION 'JOB_NOT_FOUND'; END IF;
  IF o.status <> 'IN_PROGRESS' THEN RAISE EXCEPTION 'INVALID_JOB_STATE'; END IF;
  IF o.service_otp_hash IS NOT NULL AND o.service_otp_verified IS NOT TRUE THEN
    RAISE EXCEPTION 'OTP_REQUIRED';
  END IF;
  IF o.payment_status='unpaid' AND p_payment_confirmed IS NOT TRUE THEN
    RAISE EXCEPTION 'PAYMENT_CONFIRMATION_REQUIRED';
  END IF;
  IF o.payment_method='upi' AND o.payment_status='unpaid'
     AND NULLIF(trim(p_payment_reference),'') IS NULL
  THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_REQUIRED'; END IF;

  UPDATE public.orders
  SET status='COMPLETED',
      completed_at=now_ts,
      payment_status=CASE WHEN payment_status='unpaid' THEN 'paid' ELSE payment_status END
  WHERE id=p_order_id;

  UPDATE public.technician_job_dispatch
  SET status='COMPLETED', responded_at=now_ts
  WHERE order_id=p_order_id AND technician_id=p_technician_id AND status='ACCEPTED';

  RETURN jsonb_build_object('completed',true,'order_id',p_order_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.try_assign_technician(UUID,UUID,NUMERIC,NUMERIC) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.accept_technician_job(UUID,UUID) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.start_technician_job(UUID,UUID) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.create_service_otp(UUID,UUID) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.release_technician_assignment(UUID,UUID,TEXT) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.verify_service_otp(UUID,TEXT,UUID) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.complete_technician_job_atomic(UUID,UUID,BOOLEAN,TEXT) TO authenticated,service_role;

COMMIT;
